<?php
use Illuminate\Support\Facades\{Artisan,Schedule,Hash};use App\Models\{User,Source,ImportRun};use App\Services\Importer;
Artisan::command('obm:admin {email}',function(){ $password=$this->secret('Enter a strong password (minimum 12 characters)');if(strlen((string)$password)<12||!filter_var($this->argument('email'),FILTER_VALIDATE_EMAIL)){$this->error('Invalid credentials');return 1;}User::updateOrCreate(['email'=>$this->argument('email')],['name'=>'OBM Administrator','password'=>Hash::make($password),'is_admin'=>true]);$this->info('Administrator saved');});
Artisan::command('obm:import',function(){foreach(Source::where('enabled',true)->cursor() as $s){if($s->last_attempt&&\Illuminate\Support\Carbon::parse($s->last_attempt)->addMinutes($s->interval_minutes)->isFuture())continue;$s->update(['last_attempt'=>now()]);$run=ImportRun::create(['source_id'=>$s->id,'status'=>'running']);try{$count=app(Importer::class)->run($s);$run->update(['status'=>'success','count'=>$count]);$s->update(['last_success'=>now()]);}catch(\Throwable $e){$run->update(['status'=>'failed','error'=>'Import failed; check source configuration and credentials']);$this->error('Source '.$s->id.' failed');}}});
Schedule::command('obm:import')->everyFiveMinutes()->withoutOverlapping(30);
Artisan::command('obm:check-links {--limit=20}',function(){ $limit=max(1,min(50,(int)$this->option('limit')));$rows=\App\Models\Entry::where('type','directory')->where(fn($q)=>$q->whereNull('link_checked_at')->orWhere('link_checked_at','<',now()->subDays(7)))->orderBy('link_checked_at')->limit($limit)->get();foreach($rows as $e){try{$status=app(\App\Services\LinkChecker::class)->check($e->url);}catch(\Throwable $x){$status='check_error';}$e->update(['link_status'=>$status,'link_checked_at'=>now()]);$this->line($e->id.' '.$status);}});
Schedule::command('obm:check-links --limit=20')->dailyAt('03:15')->withoutOverlapping(30);
